import { mkdir, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { pathToFileURL } from 'node:url'
import { loadAdminCatalog } from './admin-catalog.mjs'

const catalogPath = path.join(process.cwd(), 'functions', 'generated', 'catalog.mjs')

export async function writeAdminCatalog() {
  const catalog = await loadAdminCatalog()
  await mkdir(path.dirname(catalogPath), { recursive: true })
  const source = `// Generated by scripts/lib/write-admin-catalog.mjs during pnpm build.
// The deployed /admin page reads this snapshot after login. Do not edit by hand.
export const catalog = ${JSON.stringify(catalog, null, 2)}
`
  await writeFile(catalogPath, source, 'utf8')
  return catalogPath
}

const entry = process.argv[1]
if (entry && import.meta.url === pathToFileURL(entry).href) {
  await writeAdminCatalog()
}
